def number(tex):
 m=re.search(r'\\frac\{(-?\d+)\}\{(\d+)\}',tex)
 return S.Rational(m[1],m[2]) if m else S.Rational(re.search(r'-?\d+(?:\.\d+)?',tex)[0])
math=[];t=S.Symbol('t',nonnegative=True)
for path in ['sample-records.json','delivery-batch/accepted.json','counterfactual-records.json','rank-controlled-records.json','minimal-records.json']:
 for r in load(R/path):
  q=r['question'];H,v,m,c,ri,ro=map(number,re.findall(r'\$([^$]+)\$',q[':question/problem'])[:6]);V=v+(ri-ro)*t;Q=c*V+(m-c*v)*(v/V)**(ro/(ri-ro));to=(H-v)/(ri-ro);mass=S.simplify(Q.subs(t,to));ode=S.simplify(S.diff(Q,t)-(c*ri-ro*Q/V));initial=S.simplify(Q.subs(t,0)-m)
  assert ode==initial==0
  expected=str(Decimal(str(S.N(mass,60))).quantize(Decimal('.1'),rounding=ROUND_HALF_UP));f=q[':question/answer-fields'][0];key=f[':answer-field/correct'][1];got=next(a[':answer/value'] for a in f[':answer-field/choices'] if a[':answer/id']==key);assert number(got)==S.Rational(expected)
  math.append({'sample_ref':path,'question_id':q[':question/id'],'seed':r['generation']['seed'],'exact_mass':str(mass),'rounded_mass':expected,'overflow_time':str(to),'ode_residual':str(ode),'initial_residual':str(initial),'key_value':got,'passed':True})
